package ru.secondmemory;
import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import androidx.test.platform.app.InstrumentationRegistry;
import org.junit.Test;
import org.json.*;
import java.io.*;
import java.util.*;
import static org.junit.Assert.*;
public class RealAnalysisTest {
 private final Instrumentation inst=InstrumentationRegistry.getInstrumentation();
 private Button button(View v,String text){if(v instanceof Button&&text.contentEquals(((Button)v).getText()))return (Button)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){Button b=button(g.getChildAt(i),text);if(b!=null)return b;}}return null;}
 private void shell(String cmd)throws Exception{try(ParcelFileDescriptor fd=inst.getUiAutomation().executeShellCommand(cmd);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd)){byte[] b=new byte[512];while(in.read(b)!=-1){}}}
 @Test(timeout=600000) public void verifiedQwenActuallyAnalyzesAndCommitsOnAndroid()throws Exception{Context c=inst.getTargetContext();if(Build.VERSION.SDK_INT>=33)inst.getUiAutomation().grantRuntimePermission(c.getPackageName(),android.Manifest.permission.POST_NOTIFICATIONS);boolean had=LocalModel.ready(c);boolean wasPaused=c.getSharedPreferences("ai",0).getBoolean("paused",false);Activity a=null;String session="real-analysis-"+UUID.randomUUID();File dir=new File(c.getFilesDir(),"sessions/"+session);assertTrue(dir.mkdirs());try{
  if(!had){assertFalse("Do not overwrite an existing model",LocalModel.file(c).exists());try(ParcelFileDescriptor fd=inst.getUiAutomation().executeShellCommand("cat /data/local/tmp/second-memory-qwen.gguf");InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd);FileOutputStream out=new FileOutputStream(LocalModel.file(c))){byte[] b=new byte[1024*1024];int n;while((n=in.read(b))!=-1)out.write(b,0,n);out.getFD().sync();}assertEquals(LocalModel.SIZE,LocalModel.file(c).length());assertTrue(LocalModel.verify(c));}
  try(FileOutputStream out=new FileOutputStream(new File(dir,"transcript.jsonl"))){String[] lines={"В больнице закончилась бумага для принтера.","Решили заказать бумагу в понедельник.","Точный срок доставки пока неизвестен."};for(int i=0;i<lines.length;i++)out.write((new JSONObject().put("text",lines[i]).put("recorded_at",System.currentTimeMillis()).put("saved_at","12:00:00").toString()+"\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));out.getFD().sync();}
  c.getSharedPreferences("ai",0).edit().putBoolean("paused",false).commit();a=inst.startActivitySync(new Intent(c,AnalysisActivity.class).putExtra("session",session).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));inst.waitForIdleSync();long began=System.currentTimeMillis(),lastLog=0,until=began+480000;JSONObject result;do{if(System.currentTimeMillis()-lastLog>10000){lastLog=System.currentTimeMillis();ActivityManager.MemoryInfo mem=new ActivityManager.MemoryInfo();c.getSystemService(ActivityManager.class).getMemoryInfo(mem);android.util.Log.i("RealQwen","elapsed="+(lastLog-began)+"ms avail="+mem.availMem+" nativeHeap="+Debug.getNativeHeapAllocatedSize()+" stat="+new String(java.nio.file.Files.readAllBytes(new File("/proc/self/stat").toPath()),java.nio.charset.StandardCharsets.UTF_8));}if(System.currentTimeMillis()-began>2000&&!AnalysisService.running&&!AiJob.isActive()&&!c.getSharedPreferences("ai",0).getString("last_error","").isEmpty())fail(c.getSharedPreferences("ai",0).getString("last_error",""));result=ConversationAnalysis.load(dir);if(result.optInt("cursor")>=3)break;if(result.optInt("failures")>=3)fail("Actual Qwen could not complete: "+result+" · "+AiJob.status);Thread.sleep(500);}while(System.currentTimeMillis()<until);
  assertEquals("Foreground launch must produce committed analysis, not just a scheduled job: "+AiJob.status,3,result.optInt("cursor"));JSONArray items=result.getJSONArray("items");assertTrue("Non-task conversation must have conclusions",items.length()>0);for(int i=0;i<items.length();i++){JSONObject point=items.getJSONObject(i);assertFalse(point.getString("quote").isEmpty());assertTrue(point.getInt("line")>=1&&point.getInt("line")<=3);}
 }finally{AnalysisService.pause(c);long until=System.currentTimeMillis()+30000;while((AnalysisService.running||AiJob.isActive())&&System.currentTimeMillis()<until)Thread.sleep(100);if(a!=null){Activity close=a;inst.runOnMainSync(close::finish);}if(!had){assertTrue("Test model cleanup",LocalModel.file(c).delete());c.getSharedPreferences("ai",0).edit().putBoolean("verified",false).commit();}c.getSharedPreferences("ai",0).edit().putBoolean("paused",wasPaused).commit();}}
 @Test public void analysisControlRemainsVisibleAtLargeFont()throws Exception{Context c=inst.getTargetContext();boolean old=c.getSharedPreferences("ai",0).getBoolean("paused",false);c.getSharedPreferences("ai",0).edit().putBoolean("paused",true).commit();Activity a=null;try{shell("settings put system font_scale 1.8");Thread.sleep(800);a=inst.startActivitySync(new Intent(c,AnalysisActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));inst.waitForIdleSync();Thread.sleep(700);Activity screen=a;inst.runOnMainSync(()->{Button action=button(screen.getWindow().getDecorView(),LocalModel.ready(c)?"Начать / продолжить анализ":"Подготовить нейросеть");assertNotNull(action);android.graphics.Rect bounds=new android.graphics.Rect();assertTrue(action.getGlobalVisibleRect(bounds));assertEquals("Analysis start must be completely visible without scrolling",action.getHeight(),bounds.height());});shell("screencap -p /data/local/tmp/analysis-v14-large.png");}finally{if(a!=null){Activity close=a;inst.runOnMainSync(close::finish);}shell("settings put system font_scale 1.0");c.getSharedPreferences("ai",0).edit().putBoolean("paused",old).commit();}}
}
